"use client";
import { Avatar } from "@base-ui/react/avatar";
import { ShieldCheckIcon, ShieldOffIcon } from "lucide-react";
import { useState } from "react";

import { ActionToastProvider } from "@/components/action-toast";
import { IconTooltip } from "@/components/icon-tooltip";
import {
  EmployeeActions,
  type EmployeeActionCallbacks,
} from "@/components/plugins/employees/employee-actions";
import { EmployeeCreateDialog } from "@/components/plugins/employees/employee-create-dialog";
import { EmployeeWebsiteStatus } from "@/components/plugins/employees/employee-website-status";
import { employeeLabels, type EmployeeLabels } from "@/components/plugins/employees/labels";
import {
  EMPLOYEE_PAGE_SIZE,
  isEmployeeAdmin,
  type CreateEmployee,
  type Employee,
} from "@/components/plugins/employees/schema";
import { TablePagination } from "@/components/table-pagination";
import { matchesTableSearch, TableSearch } from "@/components/table-search";
import { cn } from "@/components/utils/cn";
import {
  tableActionCellClass,
  tableCellClass,
  tableClass,
  tableHeaderClass,
  tablePanelClass,
  tableRowClass,
} from "@/components/utils/table-styles";
import { retainRemovedItems, useOptimisticAction } from "@/components/utils/use-optimistic-action";
export { EmployeeCreateDialog } from "@/components/plugins/employees/employee-create-dialog";
export type {
  Employee,
  CreateEmployee,
  UpdateEmployee,
  VerificationResult,
} from "@/components/plugins/employees/schema";
export type { EmployeeLabels } from "@/components/plugins/employees/labels";
export interface EmployeesPageProps extends EmployeeActionCallbacks {
  employees: readonly Employee[];
  /** For server pagination, filter the full directory before supplying this page. */
  search?: string;
  onSearchChange?: (search: string) => void;
  currentUserId: string;
  /** Role from the host's authenticated session. Missing or non-admin roles render nothing. */
  currentUserRole: string | null | undefined;
  total: number;
  offset: number;
  onOffsetChange: (offset: number) => void;
  onCreate: (values: CreateEmployee) => Promise<void>;
  loading?: boolean;
  error?: boolean;
  labels?: Partial<EmployeeLabels>;
  className?: string;
}
function EmployeesPageContent({
  employees: suppliedEmployees,
  search: controlledSearch,
  onSearchChange,
  currentUserId,
  currentUserRole,
  total,
  offset,
  onOffsetChange,
  onCreate,
  loading = false,
  error = false,
  onUpdate,
  onSetWebsitePublished,
  onDelete,
  onSendVerification,
  labels: overrides,
  className,
}: EmployeesPageProps) {
  const [localSearch, setLocalSearch] = useState("");
  const search = controlledSearch ?? localSearch;
  const optimistic = useOptimisticAction(suppliedEmployees, `${currentUserId}:${offset}:${search}`);
  const employees = optimistic.value;
  const visibleTotal = Math.max(0, total + employees.length - suppliedEmployees.length);
  if (!isEmployeeAdmin(currentUserRole)) return null;
  const labels = { ...employeeLabels, ...overrides };
  // ponytail: fallback searches supplied rows; use onSearchChange for server pagination.
  const filteredEmployees = onSearchChange
    ? employees
    : employees.filter((employee) =>
        matchesTableSearch(
          search,
          employee.name,
          employee.email,
          isEmployeeAdmin(employee.role) ? labels.roleAdmin : labels.roleUser,
          employee.banned ? labels.disabled : labels.active,
          employee.emailVerified ? labels.verified : labels.unverified,
        ),
      );
  return (
    <section
      className={cn(tablePanelClass, "mx-auto w-full max-w-7xl px-0", className)}
      aria-label={labels.title}
    >
      <header className="flex flex-wrap items-center justify-between gap-4 px-6 pb-6">
        <h1 className="font-sans text-base font-semibold">{labels.title}</h1>
        <div className="ml-auto flex max-w-full flex-wrap items-center justify-end gap-2">
          <TableSearch
            value={search}
            label={labels.search}
            clearLabel={labels.clearSearch}
            onValueChange={(value) => {
              setLocalSearch(value);
              onSearchChange?.(value);
              if (onSearchChange) onOffsetChange(0);
            }}
          />
          <EmployeeCreateDialog
            currentUserRole={currentUserRole}
            disabled={loading || error || optimistic.pending}
            onCreate={(values) => {
              const employee: Employee = {
                id: `pending-${crypto.randomUUID()}`,
                name: values.name,
                email: values.email,
                role: values.role,
                emailVerified: false,
              };
              return optimistic.run(
                (rows) => [employee, ...rows],
                () => onCreate(values),
              );
            }}
            labels={labels}
          />
        </div>
      </header>
      <div className="px-6">
        <div className="min-w-0 overflow-x-auto">
          <table className={tableClass} aria-busy={loading}>
            {loading && filteredEmployees.length > 0 && (
              <caption className="sr-only">
                <output>{labels.loading}</output>
              </caption>
            )}
            <thead className="[&_tr]:border-b">
              <tr className={tableRowClass}>
                <th scope="col" className={tableHeaderClass}>
                  {labels.name}
                </th>
                <th scope="col" className={tableHeaderClass}>
                  {labels.email}
                </th>
                <th scope="col" className={tableHeaderClass}>
                  {labels.role}
                </th>
                <th scope="col" className={tableHeaderClass}>
                  {labels.status}
                </th>
                <th scope="col" className={tableHeaderClass}>
                  {labels.website}
                </th>
                <th scope="col" className={tableActionCellClass}>
                  {labels.actions}
                </th>
              </tr>
            </thead>
            <tbody className="[&_tr:last-child]:border-0">
              {retainRemovedItems(filteredEmployees, suppliedEmployees, optimistic.pending).map(
                (employee) => (
                  <tr
                    key={employee.id}
                    hidden={!filteredEmployees.some((row) => row.id === employee.id)}
                    className={tableRowClass}
                  >
                    <td
                      aria-label={employee.name}
                      className={cn(tableCellClass, "whitespace-nowrap")}
                    >
                      <div className="flex items-center gap-3">
                        <Avatar.Root className="relative flex size-8 shrink-0 overflow-hidden rounded-full bg-primary/20">
                          <Avatar.Image
                            className="size-full object-cover"
                            src={employee.image ?? undefined}
                            alt=""
                          />
                          <Avatar.Fallback className="flex size-full items-center justify-center text-xs">
                            {employee.name
                              .trim()
                              .split(/\s+/)
                              .slice(0, 2)
                              .map((part) => part.charAt(0))
                              .join("")
                              .toUpperCase()}
                          </Avatar.Fallback>
                        </Avatar.Root>
                        <span className="max-w-48 truncate font-medium" title={employee.name}>
                          {employee.name}
                        </span>
                      </div>
                    </td>
                    <td className={cn(tableCellClass, "whitespace-nowrap")}>
                      <div className="flex items-center gap-3">
                        <IconTooltip
                          label={employee.emailVerified ? labels.verified : labels.unverified}
                        >
                          <button
                            type="button"
                            aria-label={
                              employee.emailVerified ? labels.verified : labels.unverified
                            }
                            className={cn(
                              "inline-flex size-10 shrink-0 cursor-pointer items-center justify-center rounded-full outline-none focus-visible:ring-2 focus-visible:ring-ring md:size-8",
                              employee.emailVerified
                                ? "bg-status-success text-status-success-foreground"
                                : "bg-status-pending text-status-pending-foreground",
                            )}
                          >
                            {employee.emailVerified ? (
                              <ShieldCheckIcon className="size-4 shrink-0" aria-hidden="true" />
                            ) : (
                              <ShieldOffIcon className="size-4 shrink-0" aria-hidden="true" />
                            )}
                          </button>
                        </IconTooltip>
                        <span className="max-w-72 truncate" title={employee.email}>
                          {employee.email}
                        </span>
                      </div>
                    </td>
                    <td className={cn(tableCellClass, "whitespace-nowrap")}>
                      {isEmployeeAdmin(employee.role) ? labels.roleAdmin : labels.roleUser}
                    </td>
                    <td className={cn(tableCellClass, "whitespace-nowrap")}>
                      <span
                        className={cn(
                          "inline-flex items-center gap-1.5 rounded-full px-2 py-0.5 text-xs font-medium before:size-1.5 before:shrink-0 before:rounded-full before:bg-current",
                          employee.banned
                            ? "bg-status-canceled text-status-canceled-foreground"
                            : "bg-status-success text-status-success-foreground",
                        )}
                      >
                        {employee.banned ? labels.disabled : labels.active}
                      </span>
                    </td>
                    <td className={cn(tableCellClass, "whitespace-nowrap")}>
                      <EmployeeWebsiteStatus
                        published={employee.websitePublished}
                        labels={labels}
                      />
                    </td>
                    <td className={tableActionCellClass}>
                      <EmployeeActions
                        employee={employee}
                        disabled={
                          loading ||
                          error ||
                          optimistic.pending ||
                          employee.id.startsWith("pending-")
                        }
                        currentUserId={currentUserId}
                        labels={labels}
                        onSetWebsitePublished={
                          onSetWebsitePublished
                            ? (id, published) =>
                                optimistic.run(
                                  (rows) =>
                                    rows.map((row) =>
                                      row.id === id ? { ...row, websitePublished: published } : row,
                                    ),
                                  () => onSetWebsitePublished(id, published),
                                )
                            : undefined
                        }
                        onUpdate={(values) =>
                          optimistic.run(
                            (rows) =>
                              rows.map((row) =>
                                row.id === values.id
                                  ? {
                                      ...row,
                                      ...values,
                                      emailVerified:
                                        row.email === values.email && row.emailVerified,
                                    }
                                  : row,
                              ),
                            () => onUpdate(values),
                          )
                        }
                        onDelete={(id) =>
                          optimistic.run(
                            (rows) => rows.filter((row) => row.id !== id),
                            () => onDelete(id),
                          )
                        }
                        onSendVerification={onSendVerification}
                      />
                    </td>
                  </tr>
                ),
              )}
              {((error && !loading) || optimistic.error || filteredEmployees.length === 0) && (
                <tr>
                  <td colSpan={6} className={cn(tableCellClass, "py-8")}>
                    {(error && !loading) || optimistic.error ? (
                      <p role="alert" className="text-destructive">
                        {error ? labels.error : labels.updateError}
                      </p>
                    ) : (
                      <output className="text-muted-foreground">
                        {loading ? labels.loading : search.trim() ? labels.noMatches : labels.empty}
                      </output>
                    )}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
        <TablePagination
          disabled={loading || error || optimistic.pending}
          summary={`${visibleTotal} ${labels.total}`}
          page={Math.floor(offset / EMPLOYEE_PAGE_SIZE) + 1}
          pageCount={Math.max(1, Math.ceil(total / EMPLOYEE_PAGE_SIZE))}
          label={labels.title}
          previousLabel={labels.previous}
          nextLabel={labels.next}
          previousDisabled={offset <= 0}
          nextDisabled={offset + EMPLOYEE_PAGE_SIZE >= total}
          onPrevious={() => onOffsetChange(Math.max(0, offset - EMPLOYEE_PAGE_SIZE))}
          onNext={() => onOffsetChange(offset + EMPLOYEE_PAGE_SIZE)}
        />
      </div>
    </section>
  );
}

export function EmployeesPage(props: EmployeesPageProps) {
  return (
    <ActionToastProvider>
      <EmployeesPageContent {...props} />
    </ActionToastProvider>
  );
}

"use client";
import { Dialog } from "@base-ui/react/dialog";
import { PlusIcon } from "lucide-react";
import { useId, useRef, useState } from "react";

import { NativeSelect } from "@/components/native-select";
import { employeeLabels, type EmployeeLabels } from "@/components/plugins/employees/labels";
import {
  createEmployeeSchema,
  isEmployeeAdmin,
  type CreateEmployee,
} from "@/components/plugins/employees/schema";
import {
  dialogClass,
  inputClass,
  outlineButtonClass,
  primaryButtonClass,
} from "@/components/plugins/employees/styles";
import { cn } from "@/components/utils/cn";
import { submitDialogOnShortcut } from "@/components/utils/dialog-submit";

export interface EmployeeCreateDialogProps {
  /** Role from the host's authenticated session. Missing or non-admin roles render nothing. */
  currentUserRole: string | null | undefined;
  onCreate: (values: CreateEmployee) => Promise<void>;
  labels?: Partial<EmployeeLabels>;
  className?: string;
  disabled?: boolean;
}

export function EmployeeCreateDialog({
  currentUserRole,
  onCreate,
  labels: overrides,
  className,
  disabled = false,
}: EmployeeCreateDialogProps) {
  const labels = { ...employeeLabels, ...overrides };
  const id = `factory-employee-create-${useId()}`;
  const [open, setOpen] = useState(false);
  const [pending, setPending] = useState(false);
  const [failed, setFailed] = useState(false);
  const lock = useRef(false);
  if (!isEmployeeAdmin(currentUserRole)) return null;

  async function submit(form: HTMLFormElement) {
    if (lock.current) return;
    const data = new FormData(form);
    lock.current = true;
    setPending(true);
    setFailed(false);
    try {
      await onCreate(createEmployeeSchema.parse(Object.fromEntries(data)));
      form.reset();
      setOpen(false);
    } catch {
      setFailed(true);
    } finally {
      lock.current = false;
      setPending(false);
    }
  }

  return (
    <Dialog.Root
      open={open}
      onOpenChange={(next) => {
        if (pending) return;
        setFailed(false);
        setOpen(next);
      }}
    >
      <Dialog.Trigger className={cn(primaryButtonClass, className)} disabled={disabled}>
        <PlusIcon className="size-4 shrink-0" aria-hidden="true" />
        {labels.add}
      </Dialog.Trigger>
      <Dialog.Portal>
        <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
        <Dialog.Popup className={dialogClass} onKeyDownCapture={submitDialogOnShortcut}>
          <div className="space-y-2">
            <Dialog.Title className="text-lg font-semibold">{labels.add}</Dialog.Title>
            <Dialog.Description className="text-sm text-muted-foreground">
              {labels.instructions}
            </Dialog.Description>
          </div>
          <form
            className="space-y-4"
            onSubmit={(event) => {
              event.preventDefault();
              void submit(event.currentTarget);
            }}
          >
            <div className="grid gap-2">
              <label htmlFor={`${id}-name`}>{labels.name}</label>
              <input
                className={inputClass}
                id={`${id}-name`}
                name="name"
                autoComplete="name"
                maxLength={200}
                required
                readOnly={pending}
              />
            </div>
            <div className="grid gap-2">
              <label htmlFor={`${id}-email`}>{labels.email}</label>
              <input
                className={inputClass}
                id={`${id}-email`}
                name="email"
                type="email"
                autoComplete="email"
                required
                readOnly={pending}
              />
            </div>
            <div className="grid gap-2">
              <label htmlFor={`${id}-password`}>{labels.password}</label>
              <input
                className={inputClass}
                id={`${id}-password`}
                name="password"
                type="password"
                autoComplete="new-password"
                minLength={8}
                maxLength={128}
                required
                readOnly={pending}
              />
            </div>
            <div className="grid gap-2">
              <label htmlFor={`${id}-role`}>{labels.role}</label>
              <NativeSelect
                id={`${id}-role`}
                name="role"
                defaultValue="user"
                disabled={pending}
                className={inputClass}
              >
                <option value="user">{labels.roleUser}</option>
                <option value="admin">{labels.roleAdmin}</option>
              </NativeSelect>
            </div>
            {failed && (
              <p role="alert" className="text-destructive">
                {labels.createError}
              </p>
            )}
            <div className="flex flex-wrap justify-end gap-3">
              <Dialog.Close type="button" className={outlineButtonClass} disabled={pending}>
                {labels.cancel}
              </Dialog.Close>
              <button className={primaryButtonClass} type="submit" disabled={pending}>
                {pending ? labels.adding : labels.save}
              </button>
            </div>
          </form>
        </Dialog.Popup>
      </Dialog.Portal>
    </Dialog.Root>
  );
}

"use client";
import { Dialog } from "@base-ui/react/dialog";
import { PencilIcon, SendHorizontalIcon, Trash2Icon } from "lucide-react";
import { useId, useRef, useState } from "react";

import { useActionToast, ActionToastProvider } from "@/components/action-toast";
import { IconTooltip } from "@/components/icon-tooltip";
import { NativeSelect } from "@/components/native-select";
import { EmployeeWebsiteStatus } from "@/components/plugins/employees/employee-website-status";
import { employeeLabels, type EmployeeLabels } from "@/components/plugins/employees/labels";
import {
  isEmployeeAdmin,
  updateEmployeeSchema,
  type Employee,
  type UpdateEmployee,
  type VerificationResult,
} from "@/components/plugins/employees/schema";
import {
  buttonClass,
  iconButtonClass,
  primaryButtonClass,
  outlineButtonClass,
  inputClass,
  dialogClass,
} from "@/components/plugins/employees/styles";
import { cn } from "@/components/utils/cn";
import { submitDialogOnShortcut } from "@/components/utils/dialog-submit";
export interface EmployeeActionCallbacks {
  onUpdate: (values: UpdateEmployee) => Promise<void>;
  /** Persist public-profile visibility and refresh the host's employee data. */
  onSetWebsitePublished?: (id: string, published: boolean) => Promise<void>;
  onDelete: (id: string) => Promise<void>;
  /** @deprecated The employee list no longer provides an access toggle. */
  onSetBan?: (id: string, banned: boolean) => Promise<void>;
  onSendVerification: (id: string) => Promise<VerificationResult>;
}
export interface EmployeeActionsProps extends EmployeeActionCallbacks {
  employee: Employee;
  currentUserId: string;
  labels?: Partial<EmployeeLabels>;
  className?: string;
  disabled?: boolean;
}
function EmployeeActionsContent({
  employee,
  currentUserId,
  onUpdate,
  onSetWebsitePublished,
  onDelete,
  onSendVerification,
  labels: overrides,
  className,
  disabled = false,
}: EmployeeActionsProps) {
  const labels = { ...employeeLabels, ...overrides };
  const id = `factory-employee-edit-${useId()}`;
  const [editing, setEditing] = useState(false);
  const [deleting, setDeleting] = useState(false);
  const [pending, setPending] = useState(false);
  const [failedAction, setFailedAction] = useState<string | null>(null);
  const [feedback, setFeedback] = useState<{ error: boolean; message: string } | null>(null);
  const notify = useActionToast();
  const lock = useRef(false);
  const isSelf = employee.id === currentUserId;
  async function run(kind: "edit" | "remove" | "send" | "website", action: () => Promise<void>) {
    if (disabled || lock.current) return;
    lock.current = true;
    setPending(true);
    setFailedAction(null);
    setFeedback(null);
    try {
      await action();
    } catch {
      setFailedAction(kind);
      if (kind === "send")
        setFeedback({
          error: true,
          message: labels.emailError,
        });
    } finally {
      lock.current = false;
      setPending(false);
    }
  }
  return (
    <div className={cn("flex flex-col items-end gap-1", className)}>
      <div className="flex items-center justify-end gap-1">
        {!employee.emailVerified && (
          <IconTooltip label={`${labels.sendEmail} ${employee.name}`}>
            <button
              type="button"
              className={iconButtonClass}

              disabled={disabled || pending}
              aria-label={`${labels.sendEmail} ${employee.name}`}
              onClick={() =>
                void run("send", async () => {
                  const { status } = await onSendVerification(employee.id);
                  if (status === "unavailable") {
                    setFeedback({ error: true, message: labels.emailUnavailable });
                  } else {
                    notify(status === "verified" ? labels.verified : labels.emailSent);
                  }
                })
              }
            >
              <SendHorizontalIcon aria-hidden="true" />
            </button>
          </IconTooltip>
        )}
        <Dialog.Root
          open={editing}
          onOpenChange={(open) => {
            if (!pending) {
              setFailedAction(null);
              setEditing(open);
            }
          }}
        >
          <IconTooltip label={`${labels.edit} ${employee.name}`}>
            <Dialog.Trigger
              disabled={disabled || pending}
              className={iconButtonClass}

              aria-label={`${labels.edit} ${employee.name}`}
            >
              <PencilIcon className="size-4 shrink-0" aria-hidden="true" />
            </Dialog.Trigger>
          </IconTooltip>
          <Dialog.Portal>
            <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
            <Dialog.Popup className={dialogClass} onKeyDownCapture={submitDialogOnShortcut}>
              <div className="space-y-2">
                <div className="flex flex-wrap items-start justify-between gap-3">
                  <Dialog.Title className="text-lg font-semibold">{labels.editTitle}</Dialog.Title>
                  {employee.websitePublished !== undefined &&
                    (onSetWebsitePublished ? (
                      <button
                        type="button"
                        aria-label={labels.website}
                        aria-pressed={employee.websitePublished}
                        disabled={disabled || pending}
                        className="ml-auto inline-flex min-h-10 cursor-pointer items-center rounded-full focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring disabled:cursor-not-allowed disabled:opacity-50 md:min-h-8"
                        onClick={() =>
                          void run("website", async () => {
                            await onSetWebsitePublished(employee.id, !employee.websitePublished);
                            notify(labels.websiteUpdated);
                          })
                        }
                      >
                        <EmployeeWebsiteStatus
                          published={employee.websitePublished}
                          labels={labels}
                        />
                      </button>
                    ) : (
                      <EmployeeWebsiteStatus
                        published={employee.websitePublished}
                        labels={labels}
                        className="ml-auto"
                      />
                    ))}
                </div>
                <Dialog.Description className="text-sm text-muted-foreground">
                  {labels.editDescription}
                </Dialog.Description>
                {failedAction === "website" && (
                  <p role="alert" className="text-sm text-destructive">
                    {labels.websiteError}
                  </p>
                )}
              </div>
              <form
                className="space-y-4"
                onSubmit={(event) => {
                  event.preventDefault();
                  const data = new FormData(event.currentTarget);
                  void run("edit", async () => {
                    await onUpdate(
                      updateEmployeeSchema.parse({
                        ...Object.fromEntries(data),
                        id: employee.id,
                        role: isSelf ? "admin" : data.get("role"),
                      }),
                    );
                    notify(labels.updated);
                    setEditing(false);
                  });
                }}
              >
                <div className="grid gap-2">
                  <label htmlFor={`${id}-name`}>{labels.name}</label>
                  <input
                    className={inputClass}
                    id={`${id}-name`}
                    name="name"
                    defaultValue={employee.name}
                    maxLength={200}
                    required
                    readOnly={pending}
                  />
                </div>
                <div className="grid gap-2">
                  <label htmlFor={`${id}-email`}>{labels.email}</label>
                  <input
                    className={inputClass}
                    id={`${id}-email`}
                    name="email"
                    type="email"
                    defaultValue={employee.email}
                    required
                    readOnly={pending}
                  />
                </div>
                <div className="grid gap-2">
                  <label htmlFor={`${id}-role`}>{labels.role}</label>
                  <NativeSelect
                    id={`${id}-role`}
                    name="role"
                    defaultValue={isEmployeeAdmin(employee.role) ? "admin" : "user"}
                    disabled={pending || isSelf}
                    className={inputClass}
                  >
                    <option value="user">{labels.roleUser}</option>
                    <option value="admin">{labels.roleAdmin}</option>
                  </NativeSelect>
                </div>
                {failedAction === "edit" && (
                  <p role="alert" className="text-destructive">
                    {labels.editError}
                  </p>
                )}
                <div className="flex flex-wrap justify-end gap-3">
                  <button
                    type="button"
                    className={outlineButtonClass}
                    disabled={pending}
                    onClick={() => setEditing(false)}
                  >
                    {labels.cancel}
                  </button>
                  <button
                    type="submit"
                    className={primaryButtonClass}
                    disabled={disabled || pending}
                  >
                    {pending ? labels.saving : labels.saveChanges}
                  </button>
                </div>
              </form>
            </Dialog.Popup>
          </Dialog.Portal>
        </Dialog.Root>
        {!isSelf && (
          <Dialog.Root
            open={deleting}
            onOpenChange={(open) => {
              if (!pending) {
                setFailedAction(null);
                setDeleting(open);
              }
            }}
          >
            <IconTooltip label={`${labels.delete} ${employee.name}`}>
              <Dialog.Trigger
                disabled={disabled || pending}
                className={cn(
                  iconButtonClass,
                  "bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30",
                )}
                aria-label={`${labels.delete} ${employee.name}`}
              >
                <Trash2Icon className="size-4 shrink-0" aria-hidden="true" />
              </Dialog.Trigger>
            </IconTooltip>
            <Dialog.Portal>
              <Dialog.Backdrop className="fixed inset-0 z-50 bg-foreground/30" />
              <Dialog.Popup className={dialogClass}>
                <div className="space-y-2">
                  <Dialog.Title className="text-lg font-semibold">
                    {labels.deleteTitle}
                  </Dialog.Title>
                  <Dialog.Description className="text-sm text-muted-foreground">
                    {labels.deleteDescription.replace("{name}", employee.name)}
                  </Dialog.Description>
                </div>
                {failedAction === "remove" && (
                  <p role="alert" className="text-destructive">
                    {labels.deleteError}
                  </p>
                )}
                <div className="flex flex-wrap justify-end gap-3">
                  <button
                    type="button"
                    className={outlineButtonClass}
                    disabled={pending}
                    onClick={() => setDeleting(false)}
                  >
                    {labels.cancel}
                  </button>
                  <button
                    type="button"
                    className={cn(
                      buttonClass,
                      "bg-destructive/10 text-destructive hover:bg-destructive/20 hover:text-destructive focus-visible:ring-destructive/30 dark:bg-destructive/20 dark:hover:bg-destructive/30",
                    )}
                    disabled={disabled || pending}
                    onClick={() =>
                      void run("remove", async () => {
                        await onDelete(employee.id);
                        setDeleting(false);
                      })
                    }
                  >
                    {pending ? labels.deleting : labels.delete}
                  </button>
                </div>
              </Dialog.Popup>
            </Dialog.Portal>
          </Dialog.Root>
        )}
      </div>
      {feedback && (
        <p
          role={feedback.error ? "alert" : "status"}
          className={cn(
            "max-w-60 text-xs whitespace-normal",
            feedback.error ? "text-destructive" : "text-muted-foreground",
          )}
        >
          {feedback.message}
        </p>
      )}
    </div>
  );
}

